export interface CatalogDraft { displayName: string }
export class CatalogDraftStore {
  async save(input: CatalogDraft): Promise<void> {}
}
export class CatalogDraftPanel {
  private store: CatalogDraftStore = new CatalogDraftStore()
  async submitCatalog(input: CatalogDraft): Promise<void> {
    if (input.displayName.trim().length === 0) {
      promptAction.showToast({ message: 'A value is required' })
      return
    }
    this.dispatchCatalog(input)
    await this.store.save(input)
  }
  private dispatchCatalog(input: CatalogDraft): void {}
}
